// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AITaskProps, AITaskListProps } from "./ai-task.types";

import { type CSSObject } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// --- AITask ---

const taskComponentName = "AITask";

export const AITaskClasses = {
  task: "exp-textura_ai_task",
  icon: "exp-textura_ai_task_icon",
};

const generateTaskStyles = (props: AITaskProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AITaskProps["styleSlots"]>(taskComponentName, theme, variant, styleSlotsProp),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[8]),
    ...theme.typography.body.md,
    color: theme.color.content.strong,

    [`.${AITaskClasses.icon}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      width: theme.toRem(16),
      height: theme.toRem(16),
      color: theme.color.content.weak,
      flexShrink: 0,
      fontSize: theme.toRem(16),
      borderRadius: "50%",

      '&[data-state="pending"]': {
        ...styleSlots?.iconPending,
      },
      '&[data-state="completed"]': {
        color: theme.color.background.utility.success,
        ...styleSlots?.iconCompleted,
      },
      '&[data-state="loading"]': {
        ...styleSlots?.iconLoading,
      },
      '&[data-state="error"]': {
        color: theme.color.background.utility.critical,
        ...styleSlots?.iconError,
      },
      ...styleSlots?.icon,
    },

    ...styleSlots?.root,
  };
};

export const StyledAITask = styled("div", {
  shouldForwardProp: (prop) => !getExcludedDOMProps().includes(prop),
})<AITaskProps>((props) => generateTaskStyles(props));

// --- AITaskList ---

const taskListComponentName = "AITaskList";

export const AITaskListClasses = {
  list: "exp-textura_ai_task_list",
};

const generateTaskListStyles = (props: AITaskListProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AITaskListProps["styleSlots"]>(
        taskListComponentName,
        theme,
        variant,
        styleSlotsProp,
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[8]),
    ...styleSlots?.root,
  };
};

export const StyledAITaskList = styled("div", {
  shouldForwardProp: (prop) => !getExcludedDOMProps().includes(prop),
})<AITaskListProps>((props) => generateTaskListStyles(props));
